/* Теорія за підручником: informatics5, розділ 1 */
window.THEORY = window.THEORY || {}; window.THEORY.informatics5 = Object.assign(window.THEORY.informatics5 || {}, {
l1: [{"type": "tx","h": "Чи завжди робота з комп’ютером безпечна?","e": "🛡","lead": ["XXI століття — час інформаційних технологій. Комп’ютери, ноутбуки, планшети й смартфони є майже в кожній родині, і ними щодня користуються мільйони людей.","Комп’ютер — це **електричний пристрій**, а тривала робота за екраном навантажує **очі, хребет, м’язи й нервову систему**. Тому кожен користувач має знати правила безпеки й виконувати їх."],"pts": ["Неправильна поведінка → ризик **ураження струмом** або поломки техніки","Довга робота без перерви → **втома очей**, головний біль, погана постава","Правила однакові для **стаціонарного ПК, ноутбука, планшета й смартфона**"],"say": "Сьогодні з’ясуємо, які правила безпеки існують і чому кожне з них має сенс. Правило, причину якого розумієш, легше виконувати."},{"type": "tgrid","h": "Сім правил безпечної роботи за комп’ютером","e": "📋","lead": "Ці правила потрібно виконувати і в комп’ютерному класі, і вдома.","items": [["📏","Відстань 50 см","від очей до екрана монітора"],["🔌","Не торкайся проводів","розеток, задньої панелі системного блока й монітора"],["✏️","Без сторонніх предметів","не вставляй нічого в отвори й роз’єми"],["🥤","Без їжі й напоїв","крихти й рідина псують клавіатуру, можуть спричинити замикання"],["🧼","Чисті й сухі руки","вологі руки — небезпечно для електроприладу"],["⏱","Не більше 15 хв","безперервної роботи, далі — перерва"],["🚨","Дивні сигнали чи запах?","негайно повідом учителя, лаборанта або дорослих"]],"note": "Не намагайся «полагодити» комп’ютер сам: вимикати й ремонтувати техніку мають дорослі."},{"type": "tcmp","h": "Що станеться, якщо…","e": "🤔","lead": "Кожне правило можна пояснити за схемою «якщо порушити — то станеться».","cols": [["Якщо порушити","❌",["сидіти ближче за 50 см до екрана","пити сік біля клавіатури","торкатися мокрими руками проводів","грати без перерви весь вечір"]],["То станеться","⚠️",["очі швидко втомлюються, з’являється «сухість» і почервоніння","клавіші злипаються, плата може замкнути","можна отримати удар струмом","болять голова, спина й шия, погіршується сон"]]],"say": "Спробуй самостійно придумати пару «якщо… то…» для смартфона. Наприклад: якщо користуватися телефоном, лежачи в темряві, то…"},{"type": "tx","h": "Правильна поза за комп’ютером","e": "🧍","lead": "Правильна поза знімає навантаження зі спини, шиї та рук і допомагає довше не втомлюватися.","pts": ["Спина **рівна**, спираєшся на спинку стільця","Плечі **розслаблені**, лікті зігнуті приблизно під **прямим кутом**","Кисті рук лежать на клавіатурі **вільно**, не «висять» у повітрі","Ступні ніг мають **опору** — стоять на підлозі або на підставці","Верхній край екрана — приблизно на рівні очей або трохи нижче"],"note": "Якщо ноги не дістають до підлоги, підстав під них підставку або коробку — це просте рішення від втоми м’язів.","say": "Перевір себе зараз: як ти сидиш? Виправ позу за цим списком."},{"type": "tx","h": "Робоче місце: техніка, меблі, світло","e": "💡","lead": "Безпека залежить не лише від користувача, а й від того, як облаштовано робоче місце.","pts": ["**Якісні комп’ютери** — справні, з неушкодженими проводами, монітор без мерехтіння","**Спеціальні меблі** — стілець і стіл, що підходять за зростом","**Освітлення** — рівномірне; світло не повинно відбиватися в екрані й світити в очі","Кімнату варто **провітрювати**, а екран — регулярно протирати від пилу"],"note": "Не працюй за комп’ютером у темряві: різкий контраст між яскравим екраном і темною кімнатою дуже втомлює очі."},{"type": "tx","h": "Чому важлива перерва","e": "⏱","lead": ["Учневі 5 класу радять працювати за комп’ютером безперервно **не довше 15 хвилин**, а загалом за день — обмежувати екранний час.","Під час перерви зроби кілька простих вправ:"],"pts": ["**Для очей:** заплющ очі на 5 секунд, подивись угору–вниз–ліворуч–праворуч, подивись удалину у вікно","**Для тіла:** встань, потягнися, покрути плечима й головою","**Для рук:** стисни й розтисни кулаки, струсни кисті"],"say": "Перерва — це не втрата часу. Після неї мозок знову працює швидко, а помилок стає менше."},{"type": "tflow","h": "Як встановити нагадування про перерву","e": "⏰","lead": "Щоб не забути про перерву, скористайся онлайн-таймером, наприклад **Timeanddate** (timeanddate.com/timer).","items": [["🌐","Відкрий сайт","таймера в браузері"],["✏️","Задай час","наприклад, 15 хв"],["🔔","Обери звук","сигнал, який почуєш"],["🏷","Назви таймер","«Перерва!»"],["▶️","Запусти","кнопка «Готово» / «Старт»"]],"note": "Таймер є і в кожному смартфоні — у застосунку «Годинник». Хронометрувати — означає вимірювати тривалість якоїсь дії."},{"type": "tx","h": "Володарі твого часу","e": "🕰","lead": ["Корисно дослідити, на що саме ти витрачаєш свій час. Для цього протягом двох днів записуй, скільки годин ідуть на:","Результати зручно подати **таблицею** або **діаграмою**. Визнач трьох найбільших «володарів» твого часу й подумай, що варто змінити в розпорядку дня."],"pts": ["сон, навчання, спорт і активний відпочинок","роботу за комп’ютером і смартфоном","гігієну, їжу, допомогу вдома, інші заняття"],"note": "Якщо екран «забирає» більше часу, ніж сон чи прогулянки, — це сигнал змінити звички."},{"type": "tmap","h": "Безпека за комп’ютером","center": "Безпечна робота","e": "🛡","items": [["📏","Відстань","50 см до екрана"],["⏱","Час","15 хв + перерва"],["🧍","Поза","рівна спина, опора для ніг"],["🔌","Електрика","не торкатися проводів"],["💡","Робоче місце","світло, меблі, чистота"],["🚨","Неполадки","повідомити дорослих"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Яку відстань треба тримати від очей до екрана?","Чому не можна їсти й пити біля комп’ютера?","Що робити, якщо комп’ютер почав дивно пищати або з’явився запах?","Як має сидіти учень за комп’ютером? Назви 3 ознаки правильної пози.","Скільки хвилин можна працювати без перерви і що робити під час перерви?","Чи стосуються правила безпеки смартфона? Наведи приклад."]}],
l2: [{"type": "tx","h": "Чим небезпечний інтернет?","e": "🌐","lead": ["Інтернет — величезна бібліотека, кінотеатр і місце спілкування водночас. Але, як і на вулиці, у мережі можна потрапити в небезпечну ситуацію.","Щоб уникнути цього, потрібно **критично оцінювати** знайдене й дотримуватися правил безпечної поведінки."],"pts": ["повірити **неправдивій рекламі** чи фейковій новині","натрапити на **некоректні зображення** чи відео","скористатися **неперевіреними даними**","зустріти людей із **поганими намірами**","«підхопити» **комп’ютерний вірус**"],"say": "Безпечна поведінка в інтернеті — така сама навичка, як уміння переходити дорогу."},{"type": "tx","h": "Бережи свої персональні дані","e": "🔐","lead": ["Зловмисники в мережі полюють на **особисті дані** користувачів, щоб шантажувати, ошукати з грошима або тиснути на людину.","Ніколи не повідомляй в інтернеті без дозволу батьків:"],"pts": ["свою **адресу** й **номер телефону**","**школу**, у якій навчаєшся, і де проводиш вільний час","**паролі** від акаунтів (навіть друзям!)","фото документів, банківських карток батьків"],"note": "Розповідай батькам або старшим, які сайти ти відвідуєш і які пропозиції отримуєш з інтернету."},{"type": "tx","h": "Хто насправді по той бік екрана?","e": "🎭","lead": "У мережі люди можуть приховувати своє **справжнє обличчя** й **наміри**. Аватарка та ім’я можуть бути вигаданими: «однолітком» може виявитися доросла людина.","pts": ["На **агресію, образи, погрози** не відповідай — це лише розпалює конфлікт","Якщо тебе змушують робити те, від чого **незатишно** чи страшно, — припини спілкування","**Не погоджуйся** на зустріч з онлайн-знайомим без участі батьків","Збережи знімок екрана з погрозами й покажи дорослим"],"say": "Ти маєш право в будь-який момент вийти з розмови, заблокувати людину й попросити допомоги."},{"type": "tdef","term": "Кібербулінг","e": "😠","ex": ["образливі коментарі під фото","створення групи, щоб висміювати однокласника","розсилання чужих фото без дозволу"],"note": "Якщо тебе цькують: не відповідай кривдникові, збережи докази (скриншоти), заблокуй його й розкажи дорослим. Допомогу можна отримати й на Національній дитячій «гарячій лінії» 116 111.","def": "Цькування, образи, погрози, поширення принизливих фото чи пліток про людину за допомогою інтернету, месенджерів, соцмереж."},{"type": "tdef","term": "Хакер","e": "🧑‍💻","ex": ["мотиви: помста, винагорода, розвага, бажання показати свою «кваліфікацію»","шлях до твого пристрою: неперевірені програми та посилання"],"note": "Не натискай кнопку «Завантажити» на неперевірених сайтах — так можна встановити програму, яку використають проти тебе.","def": "Людина, яка без дозволу власника на відстані проникає в комп’ютер, щоб використати, змінити або знищити дані чи програми."},{"type": "tdef","term": "Комп’ютерний вірус","e": "🦠","ex": ["знищує або пошкоджує файли","викрадає паролі та особисті дані","сповільнює роботу комп’ютера або зовсім блокує його"],"say": "Вірус названо так через схожість із біологічним вірусом: він «заражає» інші файли й пристрої та непомітно поширюється.","def": "Комп’ютерна програма, яка має здатність до прихованого самопоширення (створює свої копії без відома користувача)."},{"type": "tflow","h": "Як вірус потрапляє в комп’ютер","e": "🔓","lead": "Віруси найчастіше потрапляють разом із файлами з інтернету.","items": [["🔗","Підозріле посилання","у повідомленні чи рекламі"],["⬇️","Завантаження","програми з неперевіреного сайту"],["📦","Запуск файлу","користувач сам його відкриває"],["🦠","Зараження","вірус копіює себе й шкодить"]],"note": "Флешка друга, на якій є вірус, теж може заразити твій комп’ютер — перевіряй її антивірусом."},{"type": "tgrid","h": "Як захиститися від вірусів","e": "🛡","items": [["🏛","Офіційні сайти","завантажуй програми лише з офіційних і перевірених сайтів"],["🧪","Антивірус","перевіряй завантажені файли антивірусною програмою"],["🙋","Запитай дорослих","якщо сумніваєшся в сайті — порадься з учителем чи батьками"],["🔄","Оновлення","вчасно оновлюй систему й програми"],["🚫","Не відкривай","вкладення від незнайомців"]],"note": "Дізнайся заздалегідь, яка антивірусна програма встановлена на твоєму комп’ютері."},{"type": "tx","h": "Клавіатурний тренажер","e": "⌨️","lead": "Швидко й без помилок набирати текст — важлива навичка. Її розвивають за допомогою **клавіатурних тренажерів**.","pts": ["Пальці лежать на «домашньому» ряду: ліва рука — **Ф І В А**, права — **О Л Д Ж**","На клавішах **А** і **О** є маленькі виступи — орієнтири для пальців","Дивись на екран, а не на клавіатуру","Вправляйся щоуроку по кілька хвилин — швидкість зростатиме сама"],"say": "Сліпий десятипальцевий набір економить години часу протягом навчання."},{"type": "tmap","h": "Безпека в інтернеті","center": "Мій захист","e": "🌐","items": [["🔐","Особисті дані","не повідомляю незнайомцям"],["🎭","Незнайомці","не зустрічаюсь без батьків"],["😠","Кібербулінг","не відповідаю, кажу дорослим"],["🦠","Віруси","антивірус, перевірені сайти"],["🧑‍💻","Хакери","не завантажую невідоме"],["🙋","Допомога","батьки, вчитель, 116 111"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Які персональні дані не можна повідомляти в інтернеті?","Чому аватарка онлайн-знайомого може бути неправдивою?","Що таке комп’ютерний вірус? Яку шкоду він може завдати?","Хто такі хакери і чому не варто завантажувати програми з неперевірених сайтів?","Що робити, якщо тебе ображають у мережі?","Назви три способи захистити комп’ютер від вірусів."]}],
l3: [{"type": "tx","h": "Як використовувати інтернет з користю?","e": "📚","lead": "Інтернет допомагає вчитися будь-де й будь-коли: дома, у дорозі, на канікулах. Ти вже вмієш шукати цікаві факти, значення незнайомих слів, переглядати навчальні відео й презентації.","pts": ["В інтернеті можна навчитися **знань і вмінь**: малювати, програмувати, кататися на роликах, вишивати, ремонтувати іграшку","Але деякі речі виховуються лише **в живому спілкуванні**: поважати старших, допомагати слабшим, любити рідних","Найкращий результат — коли інтернет-уроки поєднуються з **практикою** в реальному житті"],"say": "Подумай: чого ти навчився(-лася) з інтернету останнім часом? А чого навчитися онлайн неможливо?"},{"type": "tdef","term": "Освітній портал (дитяча бібліотека)","e": "🏫","ex": ["матеріали можна переглядати онлайн","можна завантажити на свій комп’ютер і читати пізніше або роздрукувати","приклад: дитячий портал «Пустунчик»"],"def": "Сайт, що збирає перевірені навчальні матеріали для дітей: повідомлення, ігри, мультфільми, відеоінструкції, безкоштовні програми."},{"type": "tdef","term": "Інтернет-енциклопедія","e": "📖","ex": ["**універсальні** — відомості з різних наук (наприклад, Вікіпедія)","**галузеві** — дані однієї галузі: математики, літератури, географії","статті можна читати, роздруковувати, переходити за посиланнями"],"note": "Вікіпедію пишуть волонтери, тому важливі факти варто перевіряти ще в одному джерелі.","def": "Сайт із довідковими статтями, упорядкованими за темами або абеткою."},{"type": "tdef","term": "Електронна бібліотека","e": "📚","ex": ["приклад: українська бібліотека UkrLib (ukrlib.com.ua)","тут є твори зі шкільної програми, казки, вірші","зручно шукати книжку за автором чи назвою"],"def": "Сайт, що містить електронні тексти книжок, які можна читати онлайн або завантажити."},{"type": "tgrid","h": "Навчальні онлайн-ігри та курси","e": "🎮","lead": "Деякі сайти пропонують навчання у формі гри: граючи, розвиваєш спостережливість, увагу, кмітливість і покращуєш настрій. На сайтах **онлайн-навчання** можна:","items": [["📄","читати","навчальні тексти"],["🎬","дивитися","навчальні відео"],["🧮","розв’язувати","приклади й задачі з оцінюванням"],["✅","проходити","тести й вправи"]],"note": "Тобто вчитися безпосередньо в інтернеті, наче у школі. Наш портал — теж приклад такого сервісу!"},{"type": "tcmp","h": "Як обрати надійний навчальний сайт","e": "🔎","cols": [["Ознаки надійного","✅",["відомий автор чи організація","є дата оновлення","немає нав’язливої реклами","факти збігаються з іншими джерелами"]],["Привід насторожитися","⚠️",["вимагає ввести дані батьків чи картки","«виграй приз» на кожній сторінці","помилки й незрозуміле походження","просить завантажити невідому програму"]]],"say": "Перед тим як довіряти сайту, постав собі три питання: хто це написав, навіщо і чи можна це перевірити?"},{"type": "tx","h": "Як правильно шукати навчальні матеріали","e": "🔍","pts": ["Формулюй запит коротко: ключові слова без зайвих слів («будова квітки 5 клас»)","Переглядай кілька результатів, а не лише перший","Звертай увагу на адресу сайту","Зберігай корисні сайти в **закладках** браузера","Записуй джерело, звідки взято інформацію"],"note": "Знайдений текст не можна видавати за свій — треба переказати своїми словами й зазначити джерело."},{"type": "tmap","h": "Сервіси для навчання","center": "Інтернет вчить","e": "🎓","items": [["🏫","Портали","матеріали для дітей"],["📖","Енциклопедії","довідкові статті"],["📚","Бібліотеки","електронні книжки"],["🎮","Ігри","навчання граючи"],["🧑‍🏫","Онлайн-курси","уроки, тести, оцінки"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Чого можна навчитися в інтернеті, а чого — лише в реальному житті?","Чим універсальна енциклопедія відрізняється від галузевої?","Що можна робити на сайті електронної бібліотеки?","Які можливості дають сайти онлайн-навчання?","За якими ознаками можна відрізнити надійний навчальний сайт?"]}],
l4: [{"type": "tx","h": "Інтернет для власного розвитку","e": "🚀","lead": "Інтернет допомагає не лише виконувати домашні завдання, а й розвивати власні захоплення: вивчати мови, програмувати, малювати, подорожувати світом віртуально.","pts": ["**Віртуальні екскурсії** — прогулянки музеями, парками, містами без квитків і подорожей","**Мовні застосунки** (наприклад, Duolingo) — вивчення іноземних мов у формі гри","**Сайти з програмування** (code.org) — перші програми та ігри","**Онлайн-конкурси** («Бобер») — змагання з однолітками з різних країн"],"say": "Інтернет — це великі можливості для тих, хто вміє ними користуватися з розумом."},{"type": "tx","h": "Віртуальна екскурсія","e": "🏛","lead": ["Віртуальна екскурсія — це огляд реального місця (музею, парку, заповідника) за допомогою фото-панорам, відео та 3D-моделей на сайті.","Щоб провести екскурсію в групі:"],"pts": ["оберіть об’єкт (музей природи, парк, інтерактивний музей)","розподіліть ролі: екскурсовод, дослідник, оператор, оформлювач","знайдіть найцікавіші експонати й факти про них","підготуйте розповідь і покажіть екскурсію іншим групам"],"note": "Багато музеїв світу мають безкоштовні онлайн-тури — їх можна відвідати разом з родиною."},{"type": "tx","h": "Мовний бар’єр: як прочитати сайт іноземною мовою?","e": "🌍","lead": "Багато цікавих сайтів, наприклад сайт італійського музею Галілео, написано іноземними мовами. Щоб зрозуміти їх, використовують **онлайн-перекладач**.","pts": ["Найвідоміші перекладачі: **Google Перекладач**, DeepL","Можна перекладати окремі слова, речення, цілі тексти й навіть вебсторінки","Текст можна не лише вводити, а й **надиктувати** голосом"],"note": "Машинний переклад іноді помиляється, особливо з незвичними словами та ідіомами. Перевіряй зміст здоровим глуздом."},{"type": "tdef","term": "Онлайн-перекладач","e": "🔤","ex": ["поле ліворуч — **текст оригіналу**","поле праворуч — **готовий переклад**","угорі обирають мову оригіналу й мову перекладу"],"def": "Вебсервіс, який автоматично перекладає текст з однієї мови (мови оригіналу) на іншу."},{"type": "tflow","h": "Алгоритм роботи з онлайн-перекладачем","e": "🔄","items": [["📋","Скопіюй","потрібний текст на вебсторінці"],["🌐","Відкрий","перекладач translate.google.com"],["🗣","Обери мови","оригіналу й перекладу"],["📥","Встав текст","у ліве поле"],["📤","Отримай переклад","у правому полі"]],"note": "Копіювання — Ctrl + C, вставлення — Ctrl + V."},{"type": "tx","h": "Як перекласти цілу вебсторінку","e": "🖥","lead": "У браузері **Chrome** вебсторінку можна перекласти повністю, не копіюючи текст.","pts": ["Натисни правою кнопкою миші на сторінці → **«Перекласти українською»**","Або скористайся значком перекладу в адресному рядку","Щоб повернути оригінал, обери «Показати оригінал»"],"say": "Спробуй відкрити сайт будь-якого зарубіжного музею й переклади його українською."},{"type": "tx","h": "Проєкт «Сайт, який я рекомендую друзям»","e": "📢","lead": "Уяви себе маркетологом, який створює рекламний плакат про корисний сайт для однолітків.","pts": ["Обери сайт (Duolingo, Словопедія, code.org, «Бобер» тощо)","Досліди, для чого він призначений","Сплануй плакат: назва, призначення, 2–3 переваги, гасло","Створи плакат в онлайн-редакторі (наприклад, Canva/VistaCreate)","Покажи в класі й оціни роботи інших за критеріями"],"note": "Маркетолог — фахівець, який вивчає потреби людей і розповідає їм про товар чи послугу."},{"type": "tmap","h": "Інтернет для розвитку","center": "Мої можливості","e": "🚀","items": [["🏛","Віртуальні екскурсії","музеї й парки онлайн"],["🔤","Перекладачі","розумію інші мови"],["🗣","Мовні застосунки","вчу мову граючи"],["💻","Програмування","code.org"],["🏆","Конкурси","«Бобер»"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Що таке віртуальна екскурсія і як її провести в групі?","Для чого потрібен онлайн-перекладач?","Опиши алгоритм перекладу тексту з вебсторінки.","Як у браузері Chrome перекласти всю сторінку?","Чому машинному перекладу не завжди можна довіряти?"]}],
l5: [{"type": "tx","h": "Чому сучасний дослідник потребує гаджета?","e": "🔬","lead": ["Людина постійно ставить запитання й шукає на них відповіді: чому йде дощ, як працює телефон, чому одні рослини ростуть швидше за інші. Пошук відповіді на складне запитання — це **дослідження**.","Сучасні дослідники використовують гаджети: смартфоном фотографують, вимірюють, записують відео й звук, шукають відомості в інтернеті, створюють звіти."],"pts": ["Не на всі запитання людство вже знайшло відповіді","Під час пошуку істини можна **помилятися** — це нормально","Помилки допомагають уточнити припущення й рухатися далі"],"say": "Кожне велике відкриття починалося зі звичайного запитання «Чому?»."},{"type": "tdef","term": "Проблема","e": "❓","ex": ["життєва проблема: зранку не вмикається комп’ютер","навчальна: як швидко вивчити таблицю множення","наукова: чому бджоли зникають у деяких регіонах"],"note": "Вирішити проблему — означає виконати дії, що **усувають її причини**. Якщо комп’ютер не вмикається, звертаємось до технічної підтримки, яка знайде й усуне несправність.","def": "(від грец. problema — завдання) Складне теоретичне або практичне запитання, що потребує вивчення й вирішення; у науці — суперечлива ситуація, яку треба пояснити."},{"type": "tx","h": "Звідки беруться проблеми","e": "🤨","lead": ["Терміни **«проблема»**, **«проблемна ситуація»** і **«запитання»** тісно пов’язані: запитання — це форма, у якій висловлюють проблему.","Учений думає, читає, розмовляє з колегами, ставить експерименти — і раптом помічає протиріччя або щось незвичайне там, де всім іншим усе здається зрозумілим."],"pts": ["**Життєві проблеми** — труднощі, які потрібно подолати","**Наукові проблеми** виникають під час дослідження певної галузі знань"],"say": "Пізнання починається зі здивування. Навчися дивуватися звичним речам — і ти помітиш проблеми, які варто дослідити."},{"type": "tdef","term": "Гіпотеза","e": "💡","ex": ["«Кішка любить молоко» — наллємо молока й подивимося, чи питиме","«Улітку в саду цвістимуть рожеві троянди» — дочекаймося літа й перевіримо"],"note": "Гіпотеза може виявитися **хибною**. Її треба підтвердити або спростувати — і це теж результат дослідження.","def": "(від давньогрец. hypothesis — основа, припущення) Здогад, припущення про можливий спосіб вирішення проблеми, яке потрібно перевірити фактами чи експериментом."},{"type": "tx","h": "Як формулювати гіпотези","e": "🗣","lead": ["Гіпотези народжуються з логічних міркувань і з інтуїції. Зазвичай гіпотеза пов’язує явища: припускає, як одна дія вплине на іншу.","Корисні слова для припущень:","До одного запитання можна висунути **багато** гіпотез. Наприклад, «Як птахи знаходять дорогу на південь?»:"],"pts": ["**може бути**, **можливо**, **припустимо**","**що, якщо…?**","**якщо …, то …**","орієнтуються за Сонцем і зорями","бачать згори дерева, річки, гори","летять за досвідченими птахами","мають «внутрішній компас»"],"say": "Що більше гіпотез, то більше шансів знайти правильну. Але кожну треба перевірити."},{"type": "tflow","h": "Етапи наукового дослідження","e": "🧪","lead": "Наукове дослідження — це постановка й вирішення нової проблеми, отримання нових знань.","items": [["🎯","Тема і проблема","запитання, мета дослідження"],["📚","Вивчення джерел","що вже відомо людству"],["🗂","Збирання матеріалу","спостереження, вимірювання, дані"],["💡","Гіпотеза","висування припущень"],["🔬","Експеримент","перевірка гіпотез"],["📊","Висновки","підтверджено чи спростовано"],["📢","Представлення","звіт, презентація, відео"]]},{"type": "tcmp","h": "Причина і наслідок","e": "↔️","lead": "Під час дослідження важливо розрізняти, що є **причиною** (чому сталося), а що — **наслідком** (що сталося в результаті).","cols": [["Причина","⚙️",["діти багато часу проводять за іграми й відео","комп’ютер довго працює без перерви","рослину не поливали два тижні"]],["Наслідок","🎯",["зменшується фізична активність, з’являються проблеми зі здоров’ям","комп’ютер перегрівається й сповільнюється","листя в’яне"]]],"note": "Один наслідок може стати причиною наступної події — так утворюються **логічні ланцюжки**: малорухливість → зниження активності → ожиріння."},{"type": "tx","h": "Гаджет — помічник дослідника","e": "📱","pts": ["📷 **Камера** — фото й відео спостережень","🎙 **Диктофон** — запис інтерв’ю, звуків природи","📏 **Датчики** — вимірювання кроків, освітленості, нахилу","🌐 **Пошук** — знайти, що вже відомо про проблему","📝 **Нотатки** — записати дані й висновки","📊 **Програми** — побудувати таблицю, діаграму, логічний ланцюжок"],"say": "Головне — не гаджет, а запитання, яке ти досліджуєш. Гаджет лише допомагає зібрати й опрацювати дані."},{"type": "tmap","h": "Дослідження","center": "Від запитання до відкриття","e": "🔬","items": [["❓","Проблема","складне запитання"],["💡","Гіпотеза","припущення"],["🔬","Перевірка","експеримент, факти"],["↔️","Причина–наслідок","логічний ланцюжок"],["📱","Гаджет","збирає дані"],["📊","Висновок","нове знання"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Що таке проблема? Наведи приклад життєвої проблеми та способу її вирішення.","Що таке гіпотеза? Чим вона відрізняється від факту?","Які слова допомагають формулювати припущення?","Назви етапи наукового дослідження.","Визнач причину й наслідок: «Через сильний вітер у дворі впало дерево».","Чому до одного запитання можна висунути кілька гіпотез?"]}],
l6: [{"type": "tx","h": "Як люди обмінюються відомостями про світ","e": "📨","lead": ["Люди отримують і передають відомості про навколишній світ за допомогою **повідомлень**: розмовляють, пишуть, малюють, показують жести, надсилають смс.","Щоб розібратися, як це відбувається, познайомимося з трьома ключовими поняттями інформатики: **повідомлення**, **дані** та **інформація**."],"say": "Ці три слова в побуті часто плутають, але в інформатиці кожне має своє точне значення."},{"type": "tdef","term": "Повідомлення","e": "✉️","ex": ["написане слово, лист, смс","дорожній знак, сигнал світлофора","жест регулювальника, картина"],"note": "Слово **сигнал** має спільний корінь з англійським sign — знак, символ.","def": "Набір сигналів різної природи: звуків, тексту, зображень, жестів, графіків тощо."},{"type": "tx","h": "Хто кому передає повідомлення","e": "🔁","lead": ["Повідомлення можуть передаватися:","У кожному передаванні є **відправник** і **отримувач**. Отримувач може прийняти лише **зрозуміле й доступне** йому повідомлення: лист китайською мовою не стане корисним, якщо ти її не знаєш."],"pts": ["від **людини до людини** — розмова, лист, дзвінок","від **людини до пристрою** — голосова команда розумній колонці чи роботу","від **пристрою до людини** — сповіщення телефона, сигнал будильника","між **пристроями** — смартфон надсилає фото на принтер"]},{"type": "tdef","term": "Дані","e": "💾","ex": ["температура повітря, записана термометром","фото рослини у смартфоні","аудіозапис уроку"],"note": "Людина сприймає не сам предмет чи явище, а **дані** про нього. Дані фіксують органи чуття або різні пристрої: камера, мікрофон, датчик, термометр.","def": "Сукупність відомостей, зафіксованих на деякому носії для зберігання, передавання та опрацювання."},{"type": "tdef","term": "Інформація","e": "💡","ex": ["однакову інформацію можна передати **різними** повідомленнями (усно, текстом, малюнком)","одне повідомлення може нести **різну** інформацію для різних людей"],"note": "Дані, які людина використовує для прийняття рішень, стають **інформацією**; решта перетворюється на **шум**.","def": "(від лат. informatio — роз’яснення, виклад, ознайомлення) Відомості про світ, що нас оточує, та явища, які в ньому відбуваються, — те нове, що людина дізнається з повідомлень."},{"type": "tflow","h": "Від сигналу до рішення","e": "🔄","items": [["📡","Сигнали","звук, світло, знаки"],["✉️","Повідомлення","набір сигналів"],["💾","Дані","зафіксовані на носії"],["💡","Інформація","нове, зрозуміле людині"],["✅","Рішення","дія на основі інформації"]],"say": "Приклад: стрілка термометра (сигнал) → «+2 °C» (повідомлення) → запис у телефоні (дані) → «холодно» (інформація) → одягаю шапку (рішення)."},{"type": "tgrid","h": "Типи даних","e": "🗂","lead": "За способом подання дані бувають:","items": [["🔤","Текстові","слова, речення, нотатки"],["🔢","Числові","температура, ціна, кількість"],["🖼","Графічні","фото, малюнки, схеми"],["🔊","Звукові","мова, музика, звуки природи"],["🎬","Відеодані","рухомі зображення зі звуком"],["🧩","Комбіновані","презентація, вебсторінка"]],"note": "Залежно від пристрою, яким зафіксовано повідомлення, утворюються різні набори даних: мікрофон — звукові, камера — графічні та відео, термометр — числові."},{"type": "tflow","h": "Дослідно-пізнавальний цикл","e": "♻️","lead": "Під час дослідження зручно дотримуватися циклу. Його називають циклом, бо після висновку з’являються нові запитання — і все починається знову.","items": [["❓","Запитання","що хочу дізнатися"],["💡","Припущення","гіпотеза"],["📲","Збирання даних","гаджет, спостереження"],["🧠","Опрацювання","аналіз, порівняння"],["📢","Висновок","інформація й нові запитання"]]},{"type": "tx","h": "Приклад: досліджуємо кімнатну рослину","e": "🪴","lead": "Як дізнатися, як доглядати за шкільним вазоном? Використаємо смартфон:","pts": ["**Фото** рослини → графічні дані","Застосунок **Google Lens / PlantNet** розпізнає назву → текстові дані","Пошук в інтернеті: ідеальна температура, полив → числові дані","**Відеорозповідь** про догляд → відеодані"],"say": "Зверни увагу: для одного дослідження ми використали дані чотирьох різних типів."},{"type": "tmap","h": "Повідомлення, дані, інформація","center": "Обмін відомостями","e": "💡","items": [["✉️","Повідомлення","набір сигналів"],["💾","Дані","зафіксовані відомості"],["💡","Інформація","нове для людини"],["👤","Відправник","хто передає"],["🎯","Отримувач","хто приймає"],["🗂","Типи даних","текст, число, звук…"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Що таке повідомлення? Наведи три приклади сигналів.","Чим дані відрізняються від інформації?","Чому одне повідомлення може нести різну інформацію для різних людей?","Назви типи даних і пристрої, якими їх отримують.","Хто відправник і хто отримувач, коли ти даєш голосову команду смартфону?","Поясни етапи дослідно-пізнавального циклу."]}],
l7: [{"type": "tx","h": "Які пристрої потрібні мені для навчання?","e": "💻","lead": ["Люди використовують різні пристрої для роботи з даними. Кожен пристрій «вміє» отримувати, зберігати, передавати чи опрацьовувати дані певного типу.","Уяви, що тобі дають кошти на комп’ютер для навчання за умови: треба переконати, що кожна частина справді потрібна. Без яких пристроїв не обійтися, а без яких — можна?"],"say": "Щоб відповісти, з’ясуємо, які пристрої працюють із даними і що вміє комп’ютер."},{"type": "tgrid","h": "Пристрої для роботи з даними","e": "🧰","items": [["🧮","Калькулятор","розрахунки з числовими даними"],["📷","Фотоапарат, відеокамера","графічні й відеодані"],["⚖️","Електронні ваги","вага людини чи предмета"],["🎙","Диктофон","збереження звукових даних"],["⌚","Фітнес-браслет","пульс, сон, кроки, калорії"],["📱","Смартфон","місцезнаходження, погода, QR-коди"]],"note": "Записані на носій дані можна багаторазово **відтворювати** й навіть **змінювати**."},{"type": "tx","h": "Точніше за органи чуття","e": "🔭","lead": "Спеціальні пристрої дають людині змогу отримувати **точніші** дані про світ, ніж власні органи чуття.","pts": ["**Термометр** у духовці — точна температура для випікання пирога","**Телескоп** — допоміг відкрити нові планети й зорі","**Мікроскоп** — дослідження дрібних об’єктів","**Спідометр** — швидкість руху","**Барометр** — атмосферний тиск"],"say": "Рукою можна відчути «тепло», а термометр скаже точно: +23,5 °C."},{"type": "tx","h": "Передавання повідомлень на відстань","e": "📡","lead": "Текстові, звукові та графічні повідомлення передають на будь-які відстані за допомогою:","pts": ["стаціонарного телефона й **смартфона**","**радіо** та **телевізора**","**навігаторів**, дронів","**супутникового зв’язку**"],"note": "Сучасний смартфон об’єднує в собі телефон, фотоапарат, диктофон, навігатор, плеєр і комп’ютер."},{"type": "tdef","term": "Опрацювання даних","e": "⚙️","ex": ["**навігатор:** геодані із супутника → карта руху (графічні), «через 200 м поворот праворуч» (звукові), обмеження швидкості (числові)","**калькулятор:** числа → результат обчислення"],"note": "Результати пошуку чи опрацювання завжди потрібно **аналізувати й оцінювати**, перш ніж приймати рішення.","def": "Дії з даними, під час яких вони змінюються: змінюється спосіб подання, з’являються нові дані."},{"type": "tflow","h": "Що відбувається з даними","e": "🔄","lead": "Усі пристрої виконують з даними чотири основні дії — **інформаційні процеси**.","items": [["📥","Отримання","введення, вимірювання"],["💾","Зберігання","на носії"],["⚙️","Опрацювання","зміна, обчислення"],["📤","Передавання","іншій людині чи пристрою"]]},{"type": "tdef","term": "Комп’ютер","e": "🖥","ex": ["замінює калькулятор, плеєр, фотоальбом, бібліотеку, поштову скриньку","працює з текстовими, числовими, графічними, звуковими та відеоданими"],"say": "Слово «комп’ютер» походить від англійського compute — обчислювати. Перші комп’ютери справді лише рахували.","def": "Універсальний пристрій для отримання, зберігання, опрацювання й передавання даних різних типів."},{"type": "tgrid","h": "Для чого школярі використовують цифрові пристрої","e": "🎒","items": [["🔍","Пошук","повідомлень і фактів"],["📝","Тексти","підготовка й друк"],["🎬","Перегляд","зображень і навчальних відео"],["🎨","Малювання","схем і малюнків"],["🧮","Обчислення","задачі, розрахунки"],["🎵","Музика","слухання й створення"],["📂","Матеріали","збереження й презентація"],["🏋️","Тренажери","вправи й тести"]]},{"type": "ttime","h": "Як змінювались засоби роботи з інформацією","e": "🕰","items": [["Давнина","наскельні малюнки, рахування на пальцях і камінцях"],["~1450","друкарський верстат Гутенберга"],["XIX ст.","телеграф і телефон"],["1946","ENIAC — один із перших електронних комп’ютерів"],["1951","МЕОМ — перша ЕОМ у континентальній Європі (Київ, С. Лебедєв)"],["1981","персональний комп’ютер IBM PC"],["2007","перші популярні смартфони"]],"note": "Дати, як у цій стрічці, — це теж дані. Їх подають у вигляді **лінії часу**, наприклад у редакторі time.graphics."},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Наведи приклади пристроїв для роботи з числовими, звуковими та графічними даними.","Чому пристрої дають точніші дані, ніж органи чуття?","Що таке опрацювання даних? Поясни на прикладі навігатора.","Назви чотири інформаційні процеси.","Чому комп’ютер називають універсальним пристроєм?","Для чого ти сам(а) використовуєш цифрові пристрої на уроках?"]}],
l8: [{"type": "tx","h": "Як влаштований комп’ютер","e": "🖥","lead": "Люди використовують комп’ютер, щоб **вводити** дані, **зберігати** їх, **опрацьовувати** й **передавати** (виводити). Для кожної дії є свої пристрої, тому складові комп’ютера об’єднують у чотири групи.","pts": ["пристрої **введення** даних","пристрої **опрацювання** даних","пристрої **зберігання** даних","пристрої **виведення** даних"],"say": "Комп’ютер працює як людина: очі й вуха (введення), мозок (опрацювання), пам’ять (зберігання), голос і руки (виведення)."},{"type": "tgrid","h": "Пристрої введення","e": "⌨️","lead": "Призначені для введення даних у комп’ютер.","items": [["⌨️","Клавіатура","текстові й числові дані"],["🖱","Миша, тачпад","керування, вибір об’єктів"],["📠","Сканер","текстові й графічні дані з паперу"],["🎤","Мікрофон","звукові дані"],["📹","Вебкамера","відеодані"],["👆","Сенсорний екран","дотики, жести"]]},{"type": "tx","h": "Пристрої опрацювання","e": "🧠","lead": "Опрацьовує дані **процесор** — «мозок» комп’ютера. Він виконує мільярди дій за секунду: обчислює, порівнює, керує роботою інших пристроїв.","pts": ["**Процесор (ЦП)** — головний пристрій опрацювання","**Відеокарта** — опрацьовує зображення й відео, особливо в іграх і 3D","Усі складові з’єднує **материнська плата**"],"note": "Що швидший процесор, то швидше відкриваються програми й виконуються завдання."},{"type": "tcmp","h": "Пристрої зберігання","e": "💾","cols": [["Внутрішня пам’ять","🧩",["**оперативна пам’ять** — зберігає дані лише під час роботи; після вимкнення очищується","**жорсткий диск / SSD** — зберігає файли й програми постійно"]],["Зовнішні носії","💽",["**флешка**, карта пам’яті","зовнішній диск","**хмарне сховище** (Google Диск) — дані на серверах в інтернеті"]]],"note": "Не забудь зберегти документ на диск: після вимкнення комп’ютера дані з оперативної пам’яті зникають."},{"type": "tgrid","h": "Пристрої виведення","e": "🖨","lead": "Показують або видають результати роботи комп’ютера.","items": [["🖥","Монітор","текст, зображення, відео"],["🖨","Принтер","друк на папері"],["🔊","Колонки, навушники","звук"],["📽","Проєктор","зображення на великий екран"],["🧊","3D-принтер","об’ємні предмети"]]},{"type": "tdef","term": "Модель","e": "🧩","ex": ["**матеріальна модель:** глобус, макет комп’ютера, іграшкова машинка","**інформаційна модель:** опис, схема, таблиця, креслення, карта знань"],"note": "Інформаційна модель містить лише ті властивості об’єкта, що важливі для розв’язування конкретної задачі.","def": "Матеріальний або уявний об’єкт, який під час дослідження замінює реальний об’єкт-оригінал, зберігаючи його суттєві для задачі властивості."},{"type": "tdef","term": "Інфографіка","e": "📊","ex": ["плакат «Як мити руки» з малюнками","схема метро","діаграма «Скільки часу я сплю, вчуся й граю»"],"say": "Інфографіка допомагає зрозуміти складне за кілька секунд.","def": "Сукупність зображень, діаграм і мінімуму тексту, що дає легкий і зрозумілий огляд теми."},{"type": "tdef","term": "Карта знань","e": "🧠","ex": ["центр — «Комп’ютер», гілки — групи пристроїв, підгілки — конкретні пристрої","може містити текст, малюнки, значки, файли, посилання","створюють на папері або в програмах (наприклад, Coggle, MindMeister)"],"def": "Засіб графічного подання інформаційної моделі: від центрального поняття відходять гілки до пов’язаних з ним об’єктів."},{"type": "tflow","h": "Як створити карту знань","e": "🗺","items": [["🎯","Центр","головне поняття"],["🌿","Гілки","4–6 основних груп"],["🍃","Підгілки","приклади, деталі"],["🎨","Оформлення","кольори, значки"],["🔗","Зв’язки","стрілки між гілками"]]},{"type": "tmap","h": "Складові комп’ютера","center": "Комп’ютер","e": "🖥","items": [["⌨️","Введення","клавіатура, миша, мікрофон"],["🧠","Опрацювання","процесор"],["💾","Зберігання","пам’ять, диск, флешка"],["🖨","Виведення","монітор, принтер, колонки"],["🔌","З’єднання","материнська плата"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["На які чотири групи поділяють складові комп’ютера?","Наведи по два пристрої введення й виведення.","Який пристрій опрацьовує дані?","Чим оперативна пам’ять відрізняється від жорсткого диска?","Що таке інфографіка та карта знань? Для чого їх створюють?","Чим матеріальна модель відрізняється від інформаційної?"]}],
l9: [{"type": "tx","h": "Як навчитися керувати комп’ютерними пристроями?","e": "🤖","lead": ["Керувати пристроєм — означає давати йому **команди**, які він виконує. Щоб пристрій зробив саме те, що потрібно, команди треба подати в правильному порядку. Така послідовність команд називається **алгоритмом**.","Люди щодня створюють і виконують алгоритми: на роботі, вулиці, вдома — готують бутерброд, переходять дорогу, вмикають пральну машину."],"say": "Сьогодні дізнаємося, хто такі виконавці алгоритмів і якими способами можна записати алгоритм."},{"type": "tdef","term": "Алгоритм","e": "📜","ex": ["рецепт приготування страви","інструкція до конструктора","правила переходу дороги"],"note": "Кожен алгоритм має **виконавця** — того, хто виконуватиме команди.","def": "Скінченна послідовність команд (вказівок), виконання яких приводить до потрібного результату."},{"type": "tdef","term": "Виконавець алгоритму","e": "🧑‍🔧","ex": ["робот-пилосос: «рухатися вперед», «повернути», «повернутися на базу»","пральна машина: «прати», «полоскати», «віджимати»","комп’ютер: «запустити програму», «зберегти», «завершити роботу»"],"def": "Людина, тварина або пристрій, що виконує команди алгоритму. Набір команд, які виконавець уміє виконувати, називають його **системою команд**."},{"type": "tcmp","h": "Людина чи машина?","e": "⚖️","cols": [["Виконавець-людина","🧑",["може мислити й сама приймає рішення","може виправити помилку в алгоритмі","зрозуміє команду, сказану по-різному"]],["Виконавець-машина","🤖",["виконує лише ті команди, які придумала людина","виконує команди **формально**","не виправить помилку, а виконає її"]]],"say": "Комп’ютер — теж виконавець: він слухняно виконує команди людини. Тому людина відповідає за правильність алгоритму."},{"type": "tdef","term": "Формальне виконання","e": "📏","ex": ["Задумай число → додай 3 → відніми 1 → додай 2 → додай 1 → додай 2 → відніми задумане число → назви результат","Результат завжди **7**, яке б число ти не задумав(ла)! Перевір."],"def": "Виконання алгоритму команда за командою, точно в заданому порядку, без жодних змін ні в послідовності, ні в самих командах."},{"type": "tx","h": "Словесний спосіб опису","e": "📝","lead": "Алгоритм записують звичайними реченнями, пронумерувавши кроки. Наприклад, бутерброд:","pts": ["1. Узяти скибочку хліба","2. Намастити її з одного боку маслом","3. Покласти шматок ковбаси, зверху — скибочку сиру","4. Покласти листок салату й шматок помідора","5. Накрити іншою скибочкою хліба"],"note": "Словесний спосіб зручний для людей: інструкції, рецепти, правила."},{"type": "tx","h": "Графічний спосіб і блок-схеми","e": "🔷","lead": ["**Графічний спосіб** — послідовність кроків подають малюнками зі стрілками (наприклад, схема евакуації зі школи).","**Блок-схема** — графічне зображення алгоритму, де кроки зображують геометричними фігурами (блоками), з’єднаними стрілками:"],"pts": ["**овал** — початок або кінець","**прямокутник** — дія (команда)","**паралелограм** — введення або виведення даних","**ромб** — умова (розгалуження): «так» чи «ні»"],"say": "Приклад: «Чи заповнена каструля картоплею?» — якщо ні, беремо наступну картоплину, чистимо, миємо, кладемо в каструлю й знову перевіряємо умову."},{"type": "tformula","h": "Формульно-словесний спосіб","e": "🧮","lead": "У математиці кроки алгоритму часто записують формулами. Алгоритм знаходження периметра прямокутника:","f": "P = (a + b) · 2","parts": [["a","довжина","поміряти першою"],["b","ширина","поміряти другою"],["P","периметр","обчислити за формулою"]],"note": "Наприклад, a = 5 см, b = 3 см: P = (5 + 3) · 2 = 16 см."},{"type": "tdef","term": "Програма","e": "💻","ex": ["алгоритм евакуації можна намалювати для учнів і записати словами для пожежників, але комп’ютер його не виконає","щоб комп’ютер виконав алгоритм, його записують у вигляді **програми**"],"note": "Вибір способу опису алгоритму залежить від того, **хто** його виконуватиме.","def": "Алгоритм, записаний мовою, «зрозумілою» комп’ютеру (мовою програмування)."},{"type": "tx","h": "Робот-художник","e": "🎨","lead": ["Уяви робота, який рухається по клітинках і може зафарбовувати їх. Його система команд:","Щоб намалювати рядок із трьох зафарбованих клітинок: зафарбувати → праворуч → зафарбувати → праворуч → зафарбувати."],"pts": ["**вгору, вниз, ліворуч, праворуч** — перейти на сусідню клітинку","**зафарбувати** — зафарбувати клітинку, на якій стоїть робот"],"say": "Спробуй скласти алгоритм для малюнка з підручника (с. 44) і перевір його в онлайн-середовищі."},{"type": "tmap","h": "Способи опису алгоритму","center": "Алгоритм","e": "📜","items": [["📝","Словесний","нумеровані речення"],["🖼","Графічний","малюнки зі стрілками"],["🔷","Блок-схема","фігури й стрілки"],["🧮","Формульний","обчислення за формулою"],["💻","Програма","мова для комп’ютера"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Що таке алгоритм і виконавець алгоритму?","Що таке система команд виконавця? Наведи приклад.","Чим виконавець-машина відрізняється від виконавця-людини?","Що означає виконати алгоритм формально?","Які фігури використовують у блок-схемах і що вони означають?","Чому алгоритм для комп’ютера записують у вигляді програми?"]}],
l10: [{"type": "tx","h": "Де виконують алгоритми на комп’ютері?","e": "🖥","lead": ["Щоб побачити, як виконавець крок за кроком виконує алгоритм, і перевірити результат, використовують спеціальні програми — **середовища виконання алгоритмів**.","Таких середовищ є багато, кожне створено з певною метою: одні — для навчання дітей, інші — для створення ігор, анімацій, роботів."],"say": "Ти вже знайомий(а) з одним із них — середовищем Скретч."},{"type": "tdef","term": "Середовище виконання алгоритмів","e": "🧩","ex": ["Блоклі: Лабіринт","Скретч","курси «Година коду» (code.org)"],"def": "Спеціальна програма, у якій для обраних виконавців із визначеною системою команд можна описувати та виконувати алгоритми на комп’ютері."},{"type": "tgrid","h": "Складові середовища (Блоклі: Лабіринт)","e": "🧱","items": [["📋","Список завдань","рівні-випробування"],["💬","Пояснення","що потрібно зробити"],["🧱","Команди","система команд виконавця"],["🧩","Область програми","сюди складають блоки"],["🎬","Сцена","тут виконавець виконує програму"],["▶️","Кнопка запуску","запуск програми"]],"note": "Користувач перетягує блоки з командами в робочу область, з’єднує їх, як пазли, і запускає програму."},{"type": "tdef","term": "Скретч","e": "🐱","ex": ["кожен проєкт містить **виконавців** (спрайтів), **фон сцени** та **програмний код**","працює онлайн (scratch.mit.edu) і як окрема програма"],"def": "Програмне середовище для створення анімацій, ігор та інтерактивних історій. Файли, створені в Скретчі, називають **проєктами**."},{"type": "tdef","term": "Спрайт","e": "🧚","ex": ["має власну систему команд","з кожною командою пов’язана дія, яку видно на сцені","в одному проєкті може бути багато спрайтів"],"def": "Виконавець алгоритму в середовищі Скретч (з англ. sprite — світлячок, ельф). За замовчуванням це кіт із назвою «Спрайт 1»."},{"type": "tdef","term": "Скрипт","e": "📃","ex": ["складається з блоків-команд","починається з блоку-події, наприклад «коли натиснуто 🏴»"],"def": "Програма в середовищі Скретч — програмний код, що описує сценарій подій, які відбуватимуться з виконавцем."},{"type": "tgrid","h": "Групи команд у Скретчі","e": "🎨","lead": "Команди обирають у контейнері; вони об’єднані в групи різних кольорів.","items": [["🔵","Рух","йти, повернути, перейти в точку"],["🟣","Вигляд","говорити, змінити образ, розмір"],["🩷","Звук","відтворити звук"],["🟡","Події","коли натиснуто прапорець, клавішу"],["🟠","Керування","чекати, повторити, якщо"],["🟢","Олівець","малювати слід на сцені"]]},{"type": "tflow","h": "Як створити проєкт у Скретчі","e": "🚀","items": [["💡","Ідея","що відбуватиметься"],["🖼","Сцена","обрати фон"],["🧚","Спрайти","додати виконавців"],["🧩","Скрипти","скласти команди"],["▶️","Запуск","перевірити, виправити"],["💾","Збереження","зберегти проєкт"]],"say": "Приклад: виконавець «Спортсмен» кидає й ловить м’яч — для цього потрібні команди руху, зміни образу та очікування."},{"type": "tx","h": "Як перевірити, чи це середовище виконання алгоритмів","e": "🔎","lead": "Середовище виконання алгоритмів повинно мати:","pts": ["**виконавця** (одного або кількох)","його **систему команд**","місце для **складання алгоритму**","можливість **запустити** алгоритм і побачити результат"],"note": "Якщо в програмі можна лише малювати мишкою, а не складати й виконувати команди, — це не середовище виконання алгоритмів."},{"type": "tmap","h": "Середовища виконання алгоритмів","center": "Середовище","e": "🧩","items": [["🧚","Виконавець","спрайт, робот"],["🧱","Команди","система команд"],["🧩","Програма","скрипт із блоків"],["🎬","Сцена","видно результат"],["▶️","Запуск","виконання"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Що таке середовище виконання алгоритмів? Наведи приклади.","Які складові має вікно середовища Блоклі: Лабіринт?","Що таке спрайт і скрипт у Скретчі?","Назви групи команд Скретча.","Які ознаки має середовище виконання алгоритмів?"]}],
l11: [{"type": "tx","h": "Хто керує комп’ютером?","e": "🧭","lead": "Комп’ютер складається з багатьох пристроїв: процесора, пам’яті, диска, монітора, клавіатури. Хтось має узгоджувати їхню роботу й «перекладати» команди користувача мовою пристроїв. Цим займаються спеціальні програми, серед яких головну роль відіграє **операційна система** (ОС).","say": "Без операційної системи комп’ютер — це просто набір «заліза», яким неможливо керувати."},{"type": "tdef","term": "Операційна система (ОС)","e": "⚙️","ex": ["керує роботою інших програм і всіх складових комп’ютера","координує роботу окремих пристроїв","забезпечує зв’язок користувача з комп’ютером"],"note": "ОС — складні програми; їх розробляють великі команди, кожна з яких створює частину спільної програми.","def": "Набір програм, що забезпечує управління роботою комп’ютера."},{"type": "tflow","h": "Місце ОС у комп’ютері","e": "🧱","items": [["🧑","Користувач","дає команди"],["🪟","Програми","редактори, ігри, браузер"],["⚙️","Операційна система","керує всім"],["🖥","Обладнання","процесор, пам’ять, пристрої"]],"note": "Програми звертаються до обладнання не напряму, а **через ОС**."},{"type": "tgrid","h": "Поширені операційні системи","e": "💻","items": [["🪟","Windows","Microsoft; найпоширеніша на ПК"],["🍎","macOS","Apple; комп’ютери Mac"],["🐧","Linux","вільна, безкоштовна (Ubuntu, Mint)"],["🤖","Android","Google; найпоширеніша на смартфонах"],["📱","iOS","Apple; iPhone й iPad"],["🌐","ChromeOS","Google; хромбуки"]],"note": "Дізнатися, яка ОС на твоєму пристрої, можна в налаштуваннях: «Про систему» / «Про телефон»."},{"type": "tcmp","h": "Android та iOS","e": "📱","cols": [["Android","🤖",["розробила компанія **Google**","найпоширеніша мобільна ОС у світі","працює на смартфонах різних виробників","магазин застосунків **Google Play**"]],["iOS","🍎",["власна ОС компанії **Apple**","лише на iPhone та iPad","економно витрачає енергію акумулятора","магазин застосунків **App Store**"]]]},{"type": "tdef","term": "Ліцензія","e": "📄","ex": ["деякі ОС поширюються **вільно** (Linux)","для інших потрібно **придбати ліцензію** (Windows, macOS постачається з комп’ютером Apple)"],"note": "ОС зазвичай встановлює виробник комп’ютера, але користувач за потреби може встановити іншу.","def": "(лат. licentia — дозвіл) Документ, у якому зазначено дозвіл на використання об’єкта чи процесу, зокрема програми."},{"type": "tx","h": "Інтерфейс операційної системи","e": "🪟","lead": ["**Інтерфейс** — це спосіб спілкування користувача з комп’ютером. Сучасні ОС мають **графічний інтерфейс**: вікна, значки, меню, кнопки.","Елементи керування:"],"pts": ["**Робочий стіл** — головний екран зі значками","**Панель завдань** і кнопка **Пуск**","**Вікна** програм і папок","**Меню** та **контекстне меню** (права кнопка миші)","**Кошик** — сюди потрапляють видалені об’єкти"],"note": "Раніше ОС мали **текстовий інтерфейс**: команди треба було вводити з клавіатури."},{"type": "tgrid","h": "Керування мишею","e": "🖱","items": [["👆","Клацання","виділення об’єкта"],["✌️","Подвійне клацання","відкриття вікна папки, запуск програми"],["👉","Права кнопка","контекстне меню"],["✋","Перетягування","переміщення значка"],["⏳","Затримка вказівника","спливаюча підказка"]]},{"type": "tdef","term": "Ярлик","e": "🔗","ex": ["на значку ярлика в лівому нижньому куті — **стрілка**","видалення ярлика **не видаляє** сам об’єкт"],"note": "Якщо об’єкт перемістити в інше місце, старий ярлик перестане працювати — його слід видалити й створити новий.","def": "Посилання на певний об’єкт ОС (файл, папку, програму), що зберігається на носії даних. Дає змогу швидко запустити програму або відкрити документ."},{"type": "tflow","h": "Як створити ярлик на Робочому столі","e": "🧷","items": [["👉","Права кнопка","на файлі чи папці"],["📤","Надіслати","«Робочий стіл (створити ярлик)»"],["✅","Готово","ярлик зі стрілкою на столі"]],"note": "Інший спосіб: перетягнути об’єкт правою кнопкою миші на Робочий стіл і обрати «Створити ярлики»."},{"type": "tmap","h": "Операційна система","center": "ОС","e": "⚙️","items": [["🧭","Керує","програмами й пристроями"],["🪟","Інтерфейс","вікна, значки, меню"],["💻","Види","Windows, Linux, Android, iOS"],["📄","Ліцензія","вільна чи платна"],["🔗","Ярлик","швидкий доступ"],["🗑","Кошик","видалені об’єкти"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Що таке операційна система? Які її функції?","Назви 3–4 операційні системи для комп’ютерів і смартфонів.","Чим відрізняються Android та iOS?","Що таке ліцензія на програму?","Що таке ярлик і чим він відрізняється від самого файлу?","Що станеться, якщо видалити ярлик? А якщо перемістити файл, на який він посилається?"]}],
l12: [{"type": "tx","h": "Які програми потрібні для навчання?","e": "🎒","lead": "Для кожного виду роботи з даними існують свої програми: для текстів, малюнків, музики, відео, обчислень. З’являються й нові програми для навчання: тренажери, віртуальні лабораторії, навіть Minecraft Education для уроків історії, математики та програмування.","say": "Розберімося, як класифікують програми, кому вони належать і як комп’ютер зберігає дані — у файлах."},{"type": "tdef","term": "Прикладні програми","e": "🧰","ex": ["поділяються на програми **загального** та **спеціального** призначення"],"def": "Програми, призначені для розв’язування конкретних задач опрацювання даних, які користувач виконує у своїй діяльності."},{"type": "tcmp","h": "Загального чи спеціального призначення","e": "🗂","cols": [["Загального призначення","🌐",["застосовуються в різних галузях","текстові й графічні редактори","електронні таблиці, бази даних","програми для презентацій"]],["Спеціального призначення","🎯",["для певної галузі чи підприємства","відеоефекти для кіно","креслення машин і механізмів","діагностування захворювань","складання шкільного розкладу"]]]},{"type": "tx","h": "Хто створює програми","e": "👩‍💻","lead": "Комп’ютерні програми створюють **програмісти**. Розробка нового програмного забезпечення (ПЗ) — тривалий і трудомісткий процес, що потребує глибоких знань математики й інформатики.","pts": ["Будь-яка програма має **ціну** та **власника**","Більшість програм **комерційні** — за їх використання треба платити (наприклад, багато ігор)","Програмне забезпечення — **об’єкт інтелектуальної власності**; права на нього захищає Закон України «Про авторське право і суміжні права»"],"note": "Купуючи програму, ти отримуєш не саму програму у власність, а **дозвіл (ліцензію)** користуватися нею."},{"type": "tgrid","h": "Види ліцензій на програми","e": "📄","items": [["🔒","Власницькі","купуєш дозвіл, власником лишається розробник"],["🕊","Вільні","можна безкоштовно користуватися, змінювати й поширювати"],["📖","Відкриті","безкоштовна версія, але змінювати програму не можна"]],"note": "Навіть безкоштовні програми мають ліцензійну угоду, яку треба прочитати й прийняти."},{"type": "tdef","term": "Файл","e": "📁","ex": ["файли містять текстові, графічні, звукові, відеодані","ім’я файлу: **назва.розширення** — наприклад, Вишиванка.jpg"],"note": "Файли Вишиванка.jpg і Вишиванка.bmp — **різні**, бо мають різні розширення.","def": "(від англ. file — подання документа) Набір даних, що зберігається в пам’яті комп’ютера й має ім’я."},{"type": "tgrid","h": "Розширення файлів","e": "🔤","lead": "За розширенням визначають тип даних і програму, яка відкриє файл.","items": [["📝","Текст",".doc, .docx, .txt"],["🖼","Зображення",".jpg, .png, .bmp"],["🔊","Звук",".mp3, .wav"],["🎬","Відео",".mp4, .avi"],["📊","Презентація",".pptx"],["🗜","Архів",".zip"]]},{"type": "tdef","term": "Файлова система","e": "🗄","ex": ["об’єкти: **файли**, **папки**, **пристрої зберігання** (диски, флешки)","папки можуть містити інші папки — утворюється **дерево папок**","шлях до файлу: D:\\Навчання\\Інформатика\\Проєкт.docx"],"def": "Спосіб організації даних на носіях у вигляді файлів і папок. Її забезпечує операційна система."},{"type": "tx","h": "Дії з файлами й папками","e": "✂️","pts": ["**Створити** папку: права кнопка → Створити → Папку","**Перейменувати**: права кнопка → Перейменувати (або F2)","**Копіювати**: Ctrl + C → Ctrl + V","**Перемістити**: Ctrl + X → Ctrl + V або перетягнути","**Видалити**: клавіша Delete — файл потрапить у **Кошик**"],"note": "З Кошика файл можна відновити, поки Кошик не очищено."},{"type": "tmap","h": "Програми й файли","center": "Програми","e": "🧰","items": [["🌐","Загального призначення","тексти, малюнки"],["🎯","Спеціального","медицина, кіно"],["📄","Ліцензії","власницькі, вільні"],["📁","Файл","назва.розширення"],["🗄","Файлова система","папки, диски"]]},{"type": "tx","h": "Запитання для самоперевірки","e": "❓","label": "✅ Перевір себе","pts": ["Які програми називають прикладними? На які види їх поділяють?","Наведи приклади програм спеціального призначення.","Чому програмне забезпечення є об’єктом інтелектуальної власності?","Чим вільна ліцензія відрізняється від власницької?","Що таке файл? З яких частин складається його ім’я?","Яку програму слід використати, щоб відкрити файл Пісня.mp3? А Малюнок.png?"]}]
});
